export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  minStay?: number;
  minStayError?: string;
  maxGuests: number;
  basePerNight: number;
  highSurcharge: number;
  guestFee: number;     // added after discount when guests exceed guestFeeOver
  guestFeeOver: number; // Infinity disables
  flatFee: number;      // added after discount once (villa cleaning)
}

const CATEGORIES: Record<string, CategorySpec> = {
  standard: {
    maxNights: 14, maxGuests: 2,
    basePerNight: 80, highSurcharge: 30,
    guestFee: 0, guestFeeOver: Infinity, flatFee: 0,
  },
  suite: {
    maxNights: 21, maxGuests: 4,
    basePerNight: 150, highSurcharge: 60,
    guestFee: 25, guestFeeOver: 2, flatFee: 0,
  },
  villa: {
    maxNights: 28, minStay: 3, minStayError: "villa minimum stay", maxGuests: 8,
    basePerNight: 300, highSurcharge: 120,
    guestFee: 0, guestFeeOver: Infinity, flatFee: 500,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const spec = CATEGORIES[req.category as string];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: spec.minStayError };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
